#include <LVRS/ViewModel.h>
#include <LVRS/StateModel.h>
#include <LVRS/ProgressModel.h>
#include <iiSDKCore/Core/Property/ObservableReadScope.h>
#include <cmath>
#include <iostream>
#include <limits>
#include <thread>
using namespace ii;
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void take(core::Result<void> value){if(!value){if(value.error().cause)std::rethrow_exception(value.error().cause);throw std::runtime_error(value.error().message);}}
template<class T>T take(core::Result<T> value){if(!value){if(value.error().cause)std::rethrow_exception(value.error().cause);throw std::runtime_error(value.error().message);}return std::move(*value);}
using V=core::Value;
bool near(double a,double b){return std::abs(a-b)<1e-9;}
template<class Change,class F>auto port(F action){return std::make_shared<runtime::QueryPort<Change>>([action=std::move(action)](const Change& value){action(value);});}
void base(){lvrs::ViewModel model;check(model.key().empty()&&!model.busy()&&!model.has_error(),"ViewModel defaults differ");take(model.set_key("  Native  "));take(model.set_display_name("\xc2\xa0Panel\xe3\x80\x80"));take(model.set_busy(true));take(model.set_error(" Failed "));take(model.set_metadata({{"task",V(7)}}));auto snapshot=model.snapshot();check(snapshot.at("key")==V("Native")&&snapshot.at("displayName")==V("Panel")&&snapshot.at("busy")==V(true)&&snapshot.at("hasError")==V(true),"ViewModel normalization or snapshot differs");take(model.clear_error());check(!model.has_error()&&!take(model.set_busy(true)),"ViewModel no-op/error clear differs");}
void state(){lvrs::StateModel model;check(take(model.set_value(" currentValue ",V(40)))&&take(model.set_value("minimumValue",V(-10))),"State values rejected");check(model.value_or("currentValue",V{})==V(40)&&model.value_or("missing",V("fallback"))==V("fallback"),"State value resolution differs");check(model.state_keys()==std::vector<std::string>{"currentValue","minimumValue"},"State keys are not sorted");const auto revision=model.revision();check(take(model.set_value("currentValue",V(40)))&&model.revision()==revision,"A state no-op changed revision or reported failure");check(!take(model.set_value(" ",V(2)))&&model.error()=="Empty state key","Empty state key did not report the original error");check(take(model.remove_value("minimumValue"))&&!take(model.remove_value("missing"))&&model.error().empty(),"State removal contract differs");}
void patch(){lvrs::StateModel model;check(!take(model.apply_patch({}))&&take(model.apply_patch({{" a ",V(1)},{"b",V(2)}})),"State patch normalization differs");auto r=model.revision();check(take(model.apply_patch({{"a",V(1)}}))&&model.revision()==r,"An unchanged patch did not return success without revision");take(model.set_key("Panel"));auto snapshot=model.state_snapshot();check(snapshot.at("key")==V("Panel")&&snapshot.at("revision")==V(r)&&snapshot.at("empty")==V(false),"Inherited state snapshot differs");take(model.clear_values());check(model.empty()&&model.revision()==r+1&&!take(model.clear_values()),"State clear contract differs");}
void order(){lvrs::StateModel model;std::vector<lvrs::StateEvent> events;std::vector<std::string> keys;auto receiver=port<lvrs::StateChange>([&](const auto& change){events.push_back(change.event);if(change.event==lvrs::StateEvent::value)keys.push_back(change.key);check(model.value_or("a",V{})==V(1),"An observer saw an uncommitted state");});take(model.observe(receiver));take(model.set_values({{"b",V(2)},{"a",V(1)}}));check(events==std::vector{lvrs::StateEvent::revision,lvrs::StateEvent::values,lvrs::StateEvent::keys,lvrs::StateEvent::value,lvrs::StateEvent::value}&&keys==std::vector<std::string>{"a","b"},"State notification order differs");}
void nulls(){lvrs::StateModel model;take(model.set_value("empty",V{}));check(model.has_value("empty")&&model.value_or("empty",V(9))==V{},"An explicit null was confused with an absent key");take(model.remove_value("empty"));check(!model.has_value("empty")&&model.value_or("empty",V(9))==V(9),"State presence was lost");}
void progress(){lvrs::ProgressModel model;check(model.minimum_value()==0&&model.maximum_value()==100&&model.progress()==0,"Progress defaults differ");take(model.set_values({10,110,30,80}));check(near(model.normalized_start(),.2)&&near(model.normalized_current(),.7)&&near(model.fill_progress(),.5)&&near(model.fill_start(),.2),"Progress range normalization differs");take(model.set_current_value(-20));check(model.progress()==0,"Progress was not clamped");take(model.set_current_value(500));check(model.progress()==1,"Progress exceeded one");}
void reverse(){lvrs::ProgressModel model;take(model.set_values({100,0,80,20}));check(near(model.normalized_start(),.2)&&near(model.normalized_current(),.8),"A descending progress range was rejected or reversed");take(model.set_values({5,5,5,4}));check(model.progress()==0,"Zero range below maximum is not binary zero");take(model.set_current_value(5));check(model.progress()==1&&model.normalized_start()==1,"Zero range at maximum is not binary one");take(model.set_values({1,1.00000001,1,1}));check(model.progress()==0,"Near-zero range did not use the original threshold");}
void finite(){lvrs::ProgressModel model;take(model.set_values({std::nan(""),std::numeric_limits<double>::infinity(),std::nan(""),std::nan("")}));check(std::isnan(model.minimum_value())&&model.effective_minimum_value()==0&&model.effective_maximum_value()==0&&model.progress()==1,"Nonfinite direct values did not use finite fallbacks");take(model.set_values({-std::numeric_limits<double>::max(),std::numeric_limits<double>::max(),0,0}));check(model.normalized_value(std::numeric_limits<double>::infinity())==0,"Nonfinite normalized result was not zero");}
void source(){auto state=std::make_shared<lvrs::StateModel>();take(state->apply_patch({{"minimumValue",V(10)},{"maximumValue",V(110)},{"startValue",V(30)},{"currentValue",V(80)}}));lvrs::ProgressModel model;take(model.set_state_model(state));check(model.using_state_model()&&near(model.progress(),.7)&&model.state_revision()==1,"State-backed progress did not attach");take(state->set_value("currentValue",V(60)));check(near(model.progress(),.5)&&model.state_revision()==2,"State-backed progress did not update");take(model.set_state_keys({" low "," high "," begin "," value "}));take(state->apply_patch({{"low",V(0)},{"high",V(10)},{"begin",V(2)},{"value",V(7)}}));check(near(model.fill_start(),.2)&&near(model.fill_progress(),.5),"Custom state keys were not normalized");}
void conversion(){auto state=std::make_shared<lvrs::StateModel>();lvrs::ProgressModel model;take(model.set_state_model(state));take(state->set_value("currentValue",V(" 25.5 ")));check(near(model.effective_current_value(),25.5),"Numeric state text conversion differs");take(state->set_value("currentValue",V(true)));check(model.effective_current_value()==1,"Boolean state conversion differs");take(model.set_current_value(7));for(auto bad:{V("nan"),V("garbage"),V(V::Array{}),V{}}){take(state->set_value("currentValue",bad));check(model.effective_current_value()==7,"Invalid state value replaced direct fallback");}}
void lifetime(){lvrs::ProgressModel model;take(model.set_current_value(20));auto state=std::make_shared<lvrs::StateModel>();take(state->set_value("currentValue",V(80)));take(model.set_state_model(state));std::weak_ptr<lvrs::StateModel> old=state;auto r=model.state_revision();state.reset();check(old.expired()&&!model.using_state_model()&&model.progress()==.2&&model.state_revision()==r+1,"A destroyed progress state stayed retained or stale");}
void replace(){lvrs::ProgressModel model;auto first=std::make_shared<lvrs::StateModel>(),second=std::make_shared<lvrs::StateModel>();take(model.set_state_model(first));take(model.set_state_model(second));auto r=model.state_revision();take(first->set_value("currentValue",V(99)));check(model.state_revision()==r&&model.progress()==0,"Old progress source still delivered updates");take(second->set_value("currentValue",V(42)));check(model.progress()==.42,"Replacement progress source did not deliver");}
void radius(){lvrs::ProgressModel model;check(model.radius_for(1,6,100,8)==4&&model.radius_for(0,6,100,8)==6&&model.radius_for(1,6,-1,8)==0,"Progress shape radius differs");}
void ownership(){lvrs::StateModel model;bool rejected=false;std::thread other([&]{rejected=!model.set_value("x",V(1));try{(void)model.values();rejected=false;}catch(const std::logic_error&) {}});other.join();check(rejected&&model.empty(),"A native presentation model allowed cross-thread access");}
void reentrant(){lvrs::StateModel model;bool rejected=false;auto receiver=port<lvrs::StateChange>([&](const auto&){rejected=!model.set_value("nested",V(2));});take(model.observe(receiver));take(model.set_value("outer",V(1)));check(rejected&&!model.has_value("nested"),"Reentrant state mutation was not isolated");}
void fanout(){lvrs::StateModel model;int calls=0;auto first=port<lvrs::StateChange>([](const auto&){throw std::runtime_error("observer");});auto second=port<lvrs::StateChange>([&](const auto&){++calls;});take(model.observe(first));take(model.observe(second));auto result=model.set_value("x",V(1));check(!result&&model.has_value("x")&&calls==4,"Observer failure rolled back committed state or stopped delivery");}
void observation(){lvrs::ProgressModel model;std::vector<core::ObservableRead> reads;double result=core::ObservableReadScope::collect([&](auto read){reads.push_back(std::move(read));},[&]{return model.progress();});check(result==0&&!reads.empty(),"Progress getters did not expose Core observation");int changes=0;auto watch=reads.front().subscribe([&]{++changes;});take(model.set_current_value(50));check(changes==1&&model.progress()==.5,"Native progress did not publish a Core dependency");}
void unicode(){lvrs::StateModel model;take(model.set_values({{"\xee\x80\x80",V(1)},{"\xf0\x90\x80\x80",V(2)},{"\xc2\xa0 title \xe3\x80\x80",V("Native")}}));check(model.value_or("title",V{})==V("Native")&&model.state_keys()==std::vector<std::string>{"title","\xf0\x90\x80\x80","\xee\x80\x80"},"State Unicode trim or UTF-16 key order differs");}
void base_observation(){lvrs::ViewModel model;std::vector<core::ObservableRead> reads;core::ObservableReadScope::collect([&](auto read){reads.push_back(std::move(read));},[&]{return model.key();});check(reads.size()==1,"ViewModel key read widened its dependency");int changes=0;auto watch=reads[0].subscribe([&]{++changes;});take(model.set_busy(true));take(model.set_error("Other"));check(changes==0,"An unrelated ViewModel property invalidated key readers");take(model.set_key("Changed"));check(changes==1,"ViewModel key did not invalidate its readers");}
void error_fanout(){lvrs::StateModel model;take(model.set_error("Old"));auto receiver=port<lvrs::ViewModelChange>([](const auto&){throw std::runtime_error("error observer");});take(model.observe(receiver));auto result=model.set_value("valid",V(7));check(!result&&model.error().empty()&&model.value_or("valid",V{})==V(7),"A failed inherited error observer prevented the state commit");}
void pending_source(){auto state=std::make_shared<lvrs::StateModel>();lvrs::ProgressModel model;take(model.set_state_model(state));bool once=false;auto receiver=port<lvrs::ProgressChange>([&](const auto& change){if(change.event==lvrs::ProgressEvent::values&&!once){once=true;take(state->set_value("currentValue",V(75)));}});take(model.observe(receiver));take(model.set_current_value(10));check(model.progress()==.75&&once,"A source change during Progress notification was lost");}
void weak(){lvrs::StateModel model;int calls=0;auto receiver=port<lvrs::StateChange>([&](const auto&){++calls;});take(model.observe(receiver));take(model.observe(receiver));take(model.set_value("x",V(1)));check(calls==4,"Duplicate state receivers were registered");receiver.reset();take(model.set_value("x",V(2)));check(calls==4,"A dead state receiver stayed retained");}
void self_remove(){auto model=std::make_shared<lvrs::StateModel>();auto* raw=model.get();std::weak_ptr<lvrs::StateModel> old=model;auto receiver=port<lvrs::StateChange>([&](const auto& change){if(change.event==lvrs::StateEvent::revision)model.reset();});take(model->observe(receiver));take(raw->set_value("x",V(1)));check(old.expired(),"An in-flight state command leaked its removed owner");}
void configuration(){auto source=std::make_shared<lvrs::StateModel>();take(source->apply_patch({{"low",V(10)},{"high",V(110)},{"begin",V(30)},{"done",V(80)}}));lvrs::ProgressModel model;std::vector<lvrs::ProgressEvent> events;auto receiver=port<lvrs::ProgressChange>([&](const auto& change){events.push_back(change.event);check(model.minimum_value()==5&&model.current_value()==50&&model.state_keys().current=="done"&&model.state_model()==source&&near(model.progress(),.7),"Progress configuration published a partial model");});take(model.observe(receiver));check(take(model.set_configuration({5,90,20,50},{" low "," high "," begin "," done "},source)),"Configuration was not applied");check(events==std::vector{lvrs::ProgressEvent::values,lvrs::ProgressEvent::keys,lvrs::ProgressEvent::state_model,lvrs::ProgressEvent::revision,lvrs::ProgressEvent::effective},"Configuration event order or atomicity differs");check(!take(model.set_configuration({5,90,20,50},{"low","high","begin","done"},source)),"Identical configuration emitted changes");}
}
int main(int argc,char** argv){try{const std::string name=argc>1?argv[1]:"base";if(name=="base")base();else if(name=="state")state();else if(name=="patch")patch();else if(name=="order")order();else if(name=="nulls")nulls();else if(name=="progress")progress();else if(name=="reverse")reverse();else if(name=="finite")finite();else if(name=="source")source();else if(name=="conversion")conversion();else if(name=="lifetime")lifetime();else if(name=="replace")replace();else if(name=="radius")radius();else if(name=="ownership")ownership();else if(name=="reentrant")reentrant();else if(name=="fanout")fanout();else if(name=="observation")observation();else if(name=="unicode")unicode();else if(name=="base_observation")base_observation();else if(name=="error_fanout")error_fanout();else if(name=="pending_source")pending_source();else if(name=="weak")weak();else if(name=="self_remove")self_remove();else if(name=="configuration")configuration();else throw std::runtime_error("Unknown presentation model case");std::cout<<"Native presentation "<<name<<" passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
